async function grantBadge(e){e.preventDefault();if(busy)return;admin();const f=new FormData(e.currentTarget),uid=selected,badgeId=String(f.get('badge')),item=catalog[badgeId];if(!item?.enabled||item.kind!=='badge')return toast('Escolha uma insígnia ativa.');busy=true;try{const id='grant-'+crypto.randomUUID(),grant={badgeId,reason:String(f.get('reason')||'').trim().slice(0,160),week:String(f.get('week')||''),grantedAt:Date.now(),status:'active'};await update(ref(db),{['communityBadgeGrants/'+uid+'/'+id]:grant,['communityBadgeOwnership/'+uid+'/'+badgeId]:true});toast('Insígnia concedida.');await openMember(uid);}catch{toast('Não foi possível conceder a insígnia.');}finally{busy=false;}}
