async function searchMembers(term){
 const seq=++memberSearchSequence;admin();searchMemberIds=[];
 if(!term){renderMembers();return;}
 $('profile-member-list').textContent='Buscando contas…';
 const direct=/^(user\d{6,10}$|https?:\/\/|\/perfil\/)/i.test(term);
 const ids=new Set();if(direct){try{ids.add(await resolveMemberUid(term,path=>get(ref(db,path)).then(s=>s.val())));}catch{}}
 else{
  const key=term.replace(/^@/,'').toLowerCase();try{ids.add(await resolveMemberUid('@'+key,path=>get(ref(db,path)).then(s=>s.val())));}catch{}
  const queries=[query(ref(db,'communityMembers'),orderByChild('instagram'),equalTo(key),limitToLast(12)),query(ref(db,'communityMembers'),orderByChild('username'),equalTo(key),limitToLast(12))];
  if(!term.startsWith('@'))for(const prefix of new Set([term,term.replace(/\b\p{L}/gu,c=>c.toLocaleUpperCase('pt-BR'))]))queries.push(query(ref(db,'communityMembers'),orderByChild('name'),startAt(prefix),endAt(prefix+'\uf8ff'),limitToLast(12)));
  await Promise.all(queries.map(async q=>{const rows=(await get(q)).val()||{};Object.assign(members,rows);Object.keys(rows).forEach(id=>ids.add(id));}));
 }
 await Promise.all([...ids].map(id=>cacheMember(id,term)));if(seq!==memberSearchSequence||$('profile-member-search').value.trim()!==term)return;searchMemberIds=[...ids];if(searchMemberIds.length===1)rememberMember(searchMemberIds[0]);renderMembers();
}
$('profile-member-search').addEventListener('input',()=>{clearTimeout(memberSearchTimer);memberSearchSequence++;const term=$('profile-member-search').value.trim();if(!term){searchMemberIds=[];renderMembers();return;}memberSearchTimer=setTimeout(()=>searchMembers(term).catch(()=>{$('profile-member-list').textContent='Não foi possível buscar agora. Tente novamente.';}),350);});
