function showAdminView(id){const target=document.querySelector(`[data-admin-profile-view="${id}"]`);if(!target)return;document.querySelectorAll('[data-admin-profile-view]').forEach(v=>v.hidden=v!==target);document.querySelectorAll('[data-admin-profile-tab]').forEach(b=>{const active=b.dataset.adminProfileTab===id;b.classList.toggle('primary',active);b.setAttribute('aria-pressed',String(active));});const descriptions={categories:'Crie categorias e edite seus nomes e sua ordem para cada tipo de imagem.',members:'Busque uma pessoa para editar o perfil, o cargo, as imagens e as premiações.',roles:'Edite nomes e cores dos cargos e organize as pessoas em cada um.',catalog:'Cadastre avatares, capas, molduras e insígnias e controle sua disponibilidade.',goals:'Defina metas para liberar insígnias, molduras, avatares e capas.',codes:'Crie códigos para liberar imagens na coleção das pessoas.',defaults:'Escolha a foto e a capa usadas como padrão nos perfis.'};const guide=$('profile-section-guide');if(guide)guide.textContent=descriptions[id]||'';}
document.addEventListener('click',async e=>{const n=e.target.closest('[data-admin-profile-tab],[data-edit-catalog],[data-toggle-catalog],[data-profile-member],[data-revoke-grant],[data-owner-instagram],[data-revoke-image],[data-toggle-code],[data-edit-goal],[data-toggle-goal],[data-delete-goal]');if(!n)return;try{if(n.dataset.adminProfileTab){showAdminView(n.dataset.adminProfileTab);if(n.dataset.adminProfileTab==='members')await loadMembers();if(n.dataset.adminProfileTab==='codes')await loadCodes();if(n.dataset.adminProfileTab==='roles')await roleManager.start();if(n.dataset.adminProfileTab==='goals')await loadBadgeGoals();}else if(n.dataset.editCatalog)await editCatalog(n.dataset.editCatalog);else if(n.dataset.toggleCatalog){admin();const id=n.dataset.toggleCatalog;await update(ref(db,'communityProfileCatalog/'+id),{enabled:!catalog[id].enabled,updatedAt:Date.now()});await loadCatalog();}else if(n.dataset.profileMember)await openMember(n.dataset.profileMember);else if(n.dataset.revokeGrant)await revokeGrant(n.dataset.revokeGrant);else if(n.dataset.ownerInstagram)await manageOwnerInstagram(n.dataset.ownerInstagram);else if(n.dataset.editGoal)editBadgeGoal(n.dataset.editGoal);else if(n.dataset.toggleGoal){admin();const id=n.dataset.toggleGoal;await update(ref(db,'communityBadgeGoals/'+id),{enabled:!badgeGoals[id].enabled,updatedAt:Date.now()});await loadBadgeGoals();}else if(n.dataset.deleteGoal)await deleteBadgeGoal(n.dataset.deleteGoal);else if(n.dataset.revokeImage){admin();await set(ref(db,'communityImageOwnership/'+selected+'/'+n.dataset.revokeImage),null);await openMember(selected);}else if(n.dataset.toggleCode){admin();const h=n.dataset.toggleCode;await update(ref(db,'communityAvatarCodes/'+h),{enabled:!codes[h].enabled});await loadCodes();}}catch(err){toast(err.message||'Não foi possível concluir.');}});
