async function grantImage(e){e.preventDefault();admin();if(busy)return;const id=new FormData(e.currentTarget).get('assetId'),uid=selected;if(!catalog[id]?.enabled||!['avatar','cover','frame'].includes(catalog[id]?.kind)||catalog[id]?.accessRule==='admin')return toast('Selecione uma imagem disponível.');busy=true;try{await set(ref(db,'communityImageOwnership/'+uid+'/'+id),{source:'admin',grantedAt:Date.now()});await openMember(uid);toast('Imagem liberada.');}catch{toast('Não foi possível liberar.');}finally{busy=false;}}
async function digest(code){return [...new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(code)))].map(x=>x.toString(16).padStart(2,'0')).join('');}
async function loadCodes(){admin();codes=(await get(ref(db,'communityAvatarCodes'))).val()||{};const images=Object.entries(catalog).filter(([,x])=>x.enabled&&x.accessRule==='code'&&['avatar','cover','frame'].includes(x.kind));$('profile-code-form').elements.assetId.innerHTML=images.map(([id,x])=>`<option value="${id}">${esc(x.title)}</option>`).join('');$('profile-code-list').innerHTML=Object.entries(codes).map(([id,x])=>`<div class="cff-account-row"><span><b>${esc(x.label||'Código')}</b> · ${esc(catalog[x.assetId]?.title||'Imagem')}<small>${x.expiresAt?'Expira '+new Date(x.expiresAt).toLocaleDateString('pt-BR'):'Sem expiração'} · ${x.enabled?'Ativo':'Desativado'}</small></span><div class="cff-account-actions"><button type="button" class="cff-account-button" data-copy-code="${esc(x.label||'')}">Copiar</button><button class="cff-account-button" data-toggle-code="${id}">${x.enabled?'Desativar':'Ativar'}</button></div></div>`).join('')||'<p>Nenhum código criado.</p>';}
$('profile-code-form').addEventListener('submit',async e=>{e.preventDefault();admin();if(busy)return;const f=new FormData(e.currentTarget),code=String(f.get('code')).trim().toUpperCase(),assetId=String(f.get('assetId'));if(!/^[A-Z0-9-]{5,32}$/.test(code)||catalog[assetId]?.accessRule!=='code')return toast('Escolha uma imagem Via código e um código válido.');const expiresAt=f.get('expires')?Date.parse(f.get('expires')+'T23:59:59-03:00'):0;if(expiresAt&&expiresAt<Date.now())return toast('Escolha uma data futura.');busy=true;try{const id=await digest(code);if(codes[id]&&codes[id].assetId!==assetId)return toast('Este código já foi usado em outra imagem. Escolha outro.');await set(ref(db,'communityAvatarCodes/'+id),{assetId,label:code,enabled:true,expiresAt});await loadCodes();e.target.reset();toast('Código salvo: '+code);}catch{toast('Não foi possível salvar o código.');}finally{busy=false;}});

async function confirmDirectory({uid=selected,quiet=false}={}){
 admin();if(!uid||(!quiet&&busy))return;if(!quiet)busy=true;
 try{
  const [session,owner,role,old]=await Promise.all([get(ref(db,'userAccounts/'+uid+'/community')),get(ref(db,'communityOwnerInstagram')),get(ref(db,'communityAccountRoles/'+uid)),get(ref(db,'communityInstagramLinks/'+uid))]);
  let username='';
  if(owner.val()?.uid===uid&&owner.val()?.username==='nakataff')username='nakataff';
  else if(session.val()?.session){const r=await fetch(API+'/api/checkin/status?session='+encodeURIComponent(session.val().session),{cache:'no-store'}),status=await r.json();if(r.ok&&status.status==='verified')username=String(status.username||'').toLowerCase();}
  const latestProfile=(await get(ref(db,'communityProfiles/'+uid))).val();
  const synced=await syncProfileDirectory({uid,username,profile:latestProfile,roles:role.val()||{},oldLink:old.val()||{},read:path=>get(ref(db,path)).then(s=>s.val()),write:changes=>update(ref(db),changes)});
  if(!quiet)toast(synced?'Perfil confirmado no ranking.':'O perfil ainda precisa ser criado.');
 }catch(error){toast(error.message||'Não foi possível confirmar o perfil no ranking.');}
 finally{if(!quiet)busy=false;}
}

const goalForm=$('profile-goal-form');
