function fillGoalBadges(){if(!goalForm)return;const kind=goalForm.elements.rewardType.value,current=goalForm.elements.assetId.value;goalForm.elements.assetId.innerHTML='<option value="">Escolha uma recompensa</option>'+Object.entries(catalog).filter(([,x])=>x.kind===kind&&x.enabled&&x.accessRule!=='admin').map(([id,x])=>`<option value="${id}">${esc(x.title)}</option>`).join('');if([...goalForm.elements.assetId.options].some(o=>o.value===current))goalForm.elements.assetId.value=current;}
goalForm?.elements.rewardType.addEventListener('change',fillGoalBadges);

function renderBadgeGoals(){if(!goalForm)return;fillGoalBadges();const list=$('profile-goal-list');list.innerHTML=Object.entries(badgeGoals).sort(([,a],[,b])=>Number(b.updatedAt||0)-Number(a.updatedAt||0)).map(([id,g])=>`<article class="cff-admin-grant-row"><strong>${approvedImage(options,catalog,goalAssetId(g),'',catalog[goalAssetId(g)]?.title||'Recompensa')} ${esc(catalog[goalAssetId(g)]?.title||'Recompensa')}</strong><small>${esc(g.label||goalDefaultLabel(g.metric,g.target))}</small><small>${esc(GOAL_METRICS[g.metric]||g.metric)} · ${{badge:'Insígnia',frame:'Moldura',avatar:'Avatar',cover:'Capa'}[catalog[goalAssetId(g)]?.kind]||'Recompensa'} · meta ${Number(g.target).toLocaleString('pt-BR')} · ${g.enabled?'Ativo':'Desativado'}</small><div class="cff-account-actions"><button class="cff-account-button" data-edit-goal="${id}">Editar</button><button class="cff-account-button" data-toggle-goal="${id}">${g.enabled?'Desativar':'Ativar'}</button><button class="cff-account-button danger" data-delete-goal="${id}">Excluir</button></div></article>`).join('')||'<p class="cff-profile-muted">Nenhum objetivo automático cadastrado.</p>';hydrateProfileImages(list,db);}
async function loadBadgeGoals(){admin();badgeGoals=(await get(ref(db,'communityBadgeGoals'))).val()||{};renderBadgeGoals();}
function resetBadgeGoal(){if(!goalForm)return;goalForm.reset();goalForm.elements.id.value='';goalForm.elements.target.value='1';goalForm.elements.enabled.checked=true;fillGoalBadges();$('profile-goal-status').textContent='';}
function editBadgeGoal(id){const g=badgeGoals[id];if(!g||!goalForm)return;goalForm.elements.id.value=id;goalForm.elements.rewardType.value=catalog[goalAssetId(g)]?.kind||'badge';fillGoalBadges();goalForm.elements.assetId.value=goalAssetId(g);goalForm.elements.metric.value=g.metric;goalForm.elements.target.value=g.target;goalForm.elements.label.value=g.label||'';goalForm.elements.enabled.checked=g.enabled!==false;$('profile-goal-status').textContent='Editando: '+(catalog[goalAssetId(g)]?.title||'Recompensa');goalForm.scrollIntoView({behavior:'smooth',block:'center'});}
async function deleteBadgeGoal(id){admin();if(!confirm('Excluir este objetivo automático? A regra deixa de liberar novas recompensas. Itens já conquistados continuam na coleção.'))return;await set(ref(db,'communityBadgeGoals/'+id),null);await loadBadgeGoals();toast('Objetivo excluído.');}
if(goalForm){$('profile-goal-reset').addEventListener('click',resetBadgeGoal);$('profile-goals-refresh').addEventListener('click',()=>loadBadgeGoals().catch(()=>toast('Não foi possível atualizar os objetivos.')));goalForm.addEventListener('submit',async e=>{e.preventDefault();admin();if(busy)return;const f=new FormData(goalForm),existing=String(f.get('id')||''),assetId=String(f.get('assetId')||''),metric=String(f.get('metric')||''),target=Math.floor(Number(f.get('target')||0)),item=catalog[assetId];if(!item||!['badge','frame','avatar','cover'].includes(item.kind)||!item.enabled||item.accessRule==='admin')return toast('Escolha uma recompensa ativa.');if(!GOAL_METRICS[metric]||target<1||target>10000000)return toast('Confira o objetivo e a quantidade.');const id=existing||'goal-'+crypto.randomUUID(),now=Date.now(),old=badgeGoals[id];const goal={assetId,metric,target,label:String(f.get('label')||'').trim().slice(0,120),enabled:f.get('enabled')==='on',createdAt:Number(old?.createdAt)||now,updatedAt:now};busy=true;try{await update(ref(db),{['communityBadgeGoals/'+id]:goal,...(item.kind!=='badge'?{['communityProfileCatalog/'+assetId+'/accessRule']:'goal',['communityProfileCatalog/'+assetId+'/unlockBadge']:''}:{})});await loadCatalog();await loadBadgeGoals();resetBadgeGoal();toast('Objetivo e recompensa salvos.');}catch(err){toast(err.message||'Não foi possível salvar o objetivo.');}finally{busy=false;}});}

function giftFormHtml(){const assets=Object.entries(catalog).filter(([,x])=>x.enabled&&x.accessRule!=='admin');return `<section class="cff-profile-panel"><h3>Enviar presente</h3><p class="cff-profile-muted">A imagem ou insígnia é liberada para esta conta e aparece em Meus presentes.</p><form id="profile-gift-form"><label class="cff-account-field">Presente<select name="assetId" required>${assets.map(([id,x])=>`<option value="${id}">${{avatar:'Avatar',cover:'Capa',badge:'Insígnia',frame:'Moldura'}[x.kind]} · ${esc(x.title)}</option>`).join('')}</select></label><div data-gift-preview></div><label class="cff-account-field">Mensagem para a pessoa<input name="message" maxlength="160" placeholder="Ex.: Obrigado por acompanhar a Central!"></label><button class="cff-account-button primary"${assets.length?'':' disabled'}>Enviar presente</button></form><h4>Presentes enviados</h4>${Object.values(selectedGifts).sort((a,b)=>b.grantedAt-a.grantedAt).map(g=>`<div class="cff-account-row"><span>${esc(catalog[g.assetId]?.title||'Presente')}<small class="cff-admin-gift-message">${esc(g.message)}</small></span><small>${esc(new Date(g.grantedAt).toLocaleDateString('pt-BR'))}</small></div>`).join('')||'<p>Nenhum presente enviado.</p>'}</section>`;}
async function sendGift(e){e.preventDefault();admin();if(busy||!selected)return;const f=new FormData(e.currentTarget),uid=selected,id=String(f.get('assetId')),item=catalog[id];if(!item?.enabled||item.accessRule==='admin')return toast('Escolha um presente ativo.');const grantedAt=Date.now(),giftId='gift-'+crypto.randomUUID(),message=String(f.get('message')||'').trim().slice(0,160);busy=true;try{const changes={['communityGifts/'+uid+'/'+giftId]:{assetId:id,kind:item.kind,message,grantedAt}};if(item.kind==='badge'){const grantId='grant-'+crypto.randomUUID();changes['communityBadgeGrants/'+uid+'/'+grantId]={badgeId:id,reason:message,week:'',grantedAt,status:'active'};changes['communityBadgeOwnership/'+uid+'/'+id]=true;}else changes['communityImageOwnership/'+uid+'/'+id]={source:'admin',grantedAt};await update(ref(db),changes);toast('Presente enviado e liberado para '+(members[uid]?.name||'a pessoa')+'.');await openMember(uid);}catch{toast('Não foi possível enviar o presente.');}finally{busy=false;}}


async function saveMemberTitle(e){e.preventDefault();admin();if(busy||!selected)return;const uid=selected,id=String(new FormData(e.currentTarget).get('roleId')||'');if(!id)return toast('Escolha um cargo cadastrado.');busy=true;try{await roleManager.assign(uid,id);toast('Cargo da pessoa atualizado.');}catch(err){toast(err.message||'Não foi possível salvar o cargo.');}finally{busy=false;}}
const roleManager=mountRoleManager({db,auth,esc,toast,knownPeople:()=>members,resolveUid:input=>resolveMemberUid(input,path=>get(ref(db,path)).then(s=>s.val())),onCatalog:next=>{roleCatalog=next;const select=$('profile-title-form')?.elements.roleId;if(select){const current=select.value||roleForAccount(selectedRoles,next).id;select.innerHTML=(current==='legacy'?`<option value="" selected>${esc(selectedRoles.title)} · escolha um cargo</option>`:'')+roleOptions(next,current,esc);}},onAssigned:async(uid,role)=>{if(selected===uid){selectedRoles={...selectedRoles,...role};await openMember(uid);}},onOpenPerson:async uid=>{showAdminView('members');await openMember(uid);}});

setupAdminLayout({onRefreshCatalog:()=>loadCatalog(),onNewImage:()=>resetForm(),onRefreshMember:()=>selected?openMember(selected):Promise.resolve(),onCopy:()=>toast('Código copiado.')});




const categoryManager=mountCategoryManager({db,auth,esc,toast,onChange:raw=>{profileCategories=raw;updateCategoryField();loadCatalog().catch(()=>toast('Não foi possível atualizar as categorias das imagens.'));}});

